package com.github.moyingshi.osc.tv.flutter;

import android.os.Build;

import com.github.moyingshi.osc.tv.BuildConfig;

/**
 * B8 C0: native side of the single Pigeon round-trip.
 *
 * <p>Implements the interface generated by Pigeon in CI from
 * {@code flutter_module/pigeons/c0_messages.dart}. The generated file
 * {@code C0Messages.java} is not committed; see docs/b8-c0-shell.md.
 *
 * <p>Purely additive: reads only {@link BuildConfig} / {@link Build}
 * constants. No data-layer, player, settings, or Lab behavior is touched.
 */
public class C0HostApiImpl implements C0Messages.C0HostApi {

    @Override
    public String getHostInfo() {
        return "Mooyingshi " + BuildConfig.VERSION_NAME
                + " (" + BuildConfig.VERSION_CODE + ")"
                + " | " + Build.MODEL
                + " | SDK " + Build.VERSION.SDK_INT;
    }
}
